package main

import (
	"bytes"
	"context"
	_ "embed"
	"encoding/json"
	"strings"

	"github.com/pdfcpu/pdfcpu/pkg/api"
)

// applicationFormPDF is the official form generated by scripts/gen_application.py.
// Regenerate it with:  python scripts/gen_application.py && cp forms/application_form_v1.pdf apply/assets/application_form.pdf
//
//go:embed assets/application_form.pdf
var applicationFormPDF []byte

type pdfField struct {
	Name  string `json:"name"`
	Value any    `json:"value"`
}

// fillApplicationPDF produces a filled-in copy of the official application
// form, so reviewers see the same document regardless of how it was submitted.
func fillApplicationPDF(a *Applicant) ([]byte, error) {
	f := a.Form
	var text, checks []pdfField
	t := func(name, value string) { text = append(text, pdfField{name, value}) }
	c := func(name string, on bool) { checks = append(checks, pdfField{name, on}) }

	t("fullname_field", strings.Trim(f.LastName+", "+f.FirstName, ", "))
	t("addr_field", f.Address1)
	t("addr2_field", f.Address2)
	t("city_field", f.City)
	t("state_field", f.State)
	t("zip_field", f.Zip)
	t("phone_field", f.Phone)
	t("email_field", a.Email)
	t("program_field", f.Program)

	c("current_fulltime_check", f.Status == "enrolled_fulltime")
	c("current_parttime_check", f.Status == "enrolled_parttime")
	c("applying_fulltime_check", f.Status == "applying_fulltime")
	c("applying_parttime_check", f.Status == "applying_parttime")
	c("applying_other_check", f.Status == "other")
	if f.Status == "other" {
		l1, l2 := splitLine(f.StatusNote, 100)
		t("applying_other_field1", l1)
		t("applying_other_field2", l2)
	}

	t("start_date_field", f.StartDate)
	c("fulltime_field", f.Enrollment == "fulltime")
	c("parttime_field", f.Enrollment == "parttime")
	if f.Enrollment == "parttime" {
		t("parttime_details_year1_field", f.PartTimeYear1)
		t("parttime_details_year2_field", f.PartTimeYear2)
		t("parttime_details_year3_field", f.PartTimeYear3)
	}

	if cert := a.Certification; cert != nil {
		t("signature_field", "/s/ "+cert.Name+" (signed electronically)")
		t("date_field", cert.At.In(eastern).Format("01/02/2006"))
	}

	js, err := json.Marshal(map[string]any{
		"forms": []map[string]any{{"textfield": text, "checkbox": checks}},
	})
	if err != nil {
		return nil, err
	}
	var out bytes.Buffer
	if err := api.FillForm(context.Background(), bytes.NewReader(applicationFormPDF), bytes.NewReader(js), &out, nil); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

// splitLine splits s into a first line of at most n runes (breaking at a
// space where possible) and the remainder.
func splitLine(s string, n int) (string, string) {
	s = strings.Join(strings.Fields(s), " ")
	r := []rune(s)
	if len(r) <= n {
		return s, ""
	}
	cut := n
	for i := n; i > n/2; i-- {
		if r[i] == ' ' {
			cut = i
			break
		}
	}
	return strings.TrimSpace(string(r[:cut])), strings.TrimSpace(string(r[cut:]))
}
